// navHxAttrs returns the HTMX attrs we attach to every sidebar/footer nav link
// so clicking swaps only the main content area instead of reloading the page.
// The plain `href` stays so middle-click / cmd-click / no-JS still works.
func navHxAttrs(href, label string) templ.Attributes {
	attrs := templ.Attributes{
		"hx-get":      href,
		"hx-target":   "#main-content",
		"hx-swap":     "innerHTML",
		"hx-push-url": "true",
	}
	if label != "" {
		attrs["data-sidebar-item"] = label
	}
	return attrs
}

// mainContentMaxWidth picks the page-content container width per route. The
// theme page needs the extra width to host the side-by-side controls + theme
// showcase layout; everything else stays at the narrower docs default.
func mainContentMaxWidth(activeComponent string) string {
	if activeComponent == "theme" {
		return "max-w-7xl"
	}
	return "max-w-5xl"
}

// getSidebarTopItems returns the top-level icon navigation items above the component sections
func getSidebarTopItems(activeComponent string) []sidebar.Item {
	return []sidebar.Item{
		{ID: "home", Label: "Getting Started", Href: "/getting-started", Icon: sidebarHomeIcon(), Active: activeComponent == "", LinkAttrs: navHxAttrs("/getting-started", "")},
		{ID: "examples", Label: "Examples", Href: "/examples", Icon: sidebarExamplesIcon(), Active: activeComponent == "examples", LinkAttrs: navHxAttrs("/examples", "")},
		{ID: "theme", Label: "Theme", Href: "/docs/theme", Icon: sidebarThemeIcon(), Active: activeComponent == "theme", LinkAttrs: navHxAttrs("/docs/theme", "")},
		{ID: "attributions", Label: "Attributions", Href: "/attributions", Icon: sidebarAttributionsIcon(), Active: activeComponent == "attributions", LinkAttrs: navHxAttrs("/attributions", "")},
		{ID: "license", Label: "License", Href: "/license", Icon: sidebarLicenseIcon(), Active: activeComponent == "license", LinkAttrs: navHxAttrs("/license", "")},
	}
}

